# The following code was partially generated by Claude AI https://claude.ai
def generate_track_middlepoints() -> List[Tuple[int,int]]:
    """
    Generates a list of all points in the middle of the track.
    :returns: List of tuples representing points (x,y) in the middle of the track
    """ 
    break_points = create_pathline()
    out = []
    # Process each segment between consecutive break points
    for i in range(len(break_points) - 1):
        x1, y1 = break_points[i]
        x2, y2 = break_points[i + 1]
        
        # Horizontal segment
        if y1 == y2:
            start_x, end_x = min(x1, x2), max(x1, x2)
            for x in range(start_x, end_x + 1):
                out.append((x, y1))
        
        # Vertical segment
        elif x1 == x2:
            start_y, end_y = min(y1, y2), max(y1, y2)
            for y in range(start_y, end_y + 1):
                out.append((x1, y))

    return out


def generate_all_points_on_track(extended_by: int = 0) -> List[Tuple[int,int]]:
    """
    Generates a list of all points on the the track.
    :param extended_by: by how much to increase or shrink the width of resulting lines; should be at 
    most -19
    :returns: List of tuples representing points (x,y) on the track
    """

    out_set = set()
    break_points = create_pathline()
    track_middle_points = generate_track_middlepoints()
    
    # Add points for the first middlepoint:
    for y_add in range(- 20 - extended_by, 21 + extended_by):
        out_set.add((-40, 230+y_add))

    # Add all other points, except for cornerpoints
    for i in range(1, len(track_middle_points), 1):
        x1 = track_middle_points[i-1][0]
        x2 = track_middle_points[i][0]
        y1 = track_middle_points[i-1][1]
        y2 = track_middle_points[i][1]

        # Horizontal segment
        if y1 == y2:
            for y_add in range(-20 - extended_by, 21 + extended_by):
               out_set.add((x2, y2+y_add))
        
        # Vertical segment
        elif x1 == x2:
            for x_add in range(-20 - extended_by, 21 + extended_by):
                out_set.add((x2+x_add, y2))
    
    # Add points around the corners of the track
    for i in range(1, len(break_points)-1, 1):
        points_in_square = generate_square_integer_points(break_points[i], 20 + extended_by)
        for x,y in points_in_square:
            out_set.add((x,y))    

    # Make into a list and output   
    out = list(out_set)  

    return out
        
def generate_footprint_constraint_set(pos: Tuple[int,int], mode: str) -> List[Tuple[int,int]]:
    """
    Generates a set of points in which no tower can be placed given than there is already a tower placed at
    pos.
    :param pos: position in relation to which the set is computed
    :param mode: "nn" if towers of interest are non-SuperMonkeys; "ns" if one of the tower is a SuperMonkey
    and another one is not; "ss" is both towers are a super monkey. 
    :returns: List of tuples representing points (x,y) in which no tower can be built, given that
    a tower is built at pos
    """
    out = []
    if mode == "nn":
        zone_radius = 20 # footprint radius is 10 per monkey, and they cannot coincide
    elif mode == "ns":
        zone_radius = 25 # SuperMonkey has footprint 15, and non-SuperMonkey has footprint 10
    elif mode == "ss":
        zone_radius = 30 # SuperMonkey has footprint 15

    zone_circle = Circle((0,0,0), zone_radius, pos)
    min_x = pos[0] - zone_radius
    max_x = pos[0] + zone_radius
    min_y = pos[1] - zone_radius
    max_y = pos[1] + zone_radius

    for x in range(min_x, max_x+1):
        for y in range(min_y, max_y+1):
            # Check if it is in circle 
            if is_point_in_circle(zone_circle, x, y):
                out.append((x,y))
    
    return out


def generate_all_tower_placements(super_monkey: bool = False) -> List[Tuple[int, int]]: 
    """
    Generates a set of points in which towers can be placed.
    :returns: List of tuples representing points (x,y) in which towers can be places
    """
    if super_monkey:
        radius = 15
    else:
        radius = 10

    not_outside_set = set()
    for x in range(radius, 480 - radius):
        for y in range(radius, 480 - radius):
            not_outside_set.add((x,y))  
    
    too_close_to_track_set = set(generate_all_points_on_track(radius))

    out = list(not_outside_set - too_close_to_track_set)
    return out

   
def generate_coverage_dict(tower_type: str = 'Dart', upgrade_2: bool = False) -> Dict[Tuple[int,int], int]: # TODO - repurpose output to handle tower type and upgrade
    """
    Generates a dictionary containing the number of points in the middle of the track in the 
    range of a tower_type Tower, upgraded with upgrade_2 or not.
    :param tower_type: One of 'Dart', 'Tack', 'Bomb', 'Ice', 'SuperMonkey'
    :param upgrade_2: True if we want to consider the tower with upgrade 2 bought; False otherwise
    :returns: A Dict of the form (x,y): # midpoint covered
    """
    out = {}

    if not upgrade_2:
        rad = 100
    else:
        rad = 125
    tower_placements = generate_all_tower_placements()
    midpoints = generate_track_middlepoints()

    for i in range(len(tower_placements)):
        var = tower_placements[i]
        circle = Circle(color=(0,0,0), radius=rad, pos=var)
        counter = 0
        for p in midpoints:
            if is_point_in_circle(circle, p[0], p[1]):
                counter += 1
        out[var] = counter
    return out


def generate_distance_dict(alpha: float, tower_type: str = 'Dart', upgrade_1: bool = False, upgrade_2: bool = False) -> Dict[Tuple[int,int], int]: # TODO - repurpose output to handle tower type and upgrade
    """
    Generates a dictionary containing the average distance of the placement point of a tower to all
    the points in the middle of the track in the range of a tower_type Tower, upgraded with upgrade_2 or not.
    :param alpha: weight to give to count (so to the COVERAGE measure)
    :param tower_type: One of 'Dart', 'Tack', 'Bomb', 'Ice', 'SuperMonkey'
    :param upgrade_2: True if we want to consider the tower with upgrade 2 bought; False otherwise
    :returns: A Dict of the form (x,y): avegare_midpoint_distance
    """
    out = {}

    if not upgrade_2:
        rad = 100
    else:
        rad = 125
    tower_placements = generate_all_tower_placements()
    midpoints = generate_track_middlepoints()

    for i in range(len(tower_placements)):
        var = tower_placements[i]
        circle = Circle(color=(0,0,0), radius=rad, pos=var)
        counter = 0
        dist_sum = 1
        for p in midpoints:
            if is_point_in_circle(circle, p[0], p[1]):
                dist_sum += math.dist(var, p)
                counter += 1
        if counter <= 0:
            out[var] = float('Inf')
        else:
            out[var] = dist_sum/(counter*alpha)
    return out


