def get_money_constraint_rhs(round_nr: int) -> int:
    """
    Determines the amount of money the player will have at the beginning of round 
    round_nr (best case).
    :param round_nr: Round number 
    :returns: Money available to the player at the beginning of round round_nr
    """
    total_money = 650 
    rounds_info = create_rounds_dataframe()

    if round_nr == 1:
        return total_money

    round_end_money = rounds_info.loc[1:round_nr-1, 'money_round_end'].sum()
    total_money += round_end_money 


    max_RBE = rounds_info.loc[1:round_nr-1,'RBE_Cash'].sum()
    total_money += max_RBE

    return total_money  


